import{_ as a}from"./AppLayout-f385e0bb.js";import{o,c as s,w as c,a as e,e as l,h as d,F as u,g as r,t as i}from"./app-d381a890.js";import"./ApplicationLogo-e56e6a6d.js";import"./_plugin-vue_export-helper-c27b6911.js";const h={class:"max-w-4xl mx-auto p-4 lg:p-8"},m=e("h1",{class:"text-2xl font-semibold text-gray-900"},"Terms of Use & Disclaimer",-1),y=e("p",{class:"mt-2 text-sm text-gray-500"}," This website is operated by Xtreme Motors Inc. Throughout the site, the terms “we”, “us” and “our” refer to Xtreme Motors Inc.. We offer this website, including all information, tools and services available from this site to you, the user, conditioned upon your acceptance of all terms, conditions, policies and notices stated here. By visiting our site and/ or contacting us you engage in our “Service” and agree to be bound by the following terms and conditions. These Terms & Conditions apply to all users of the site, including without limitation users including browsers, vendors, customers, merchants, and/ or contributors of content. Please read these Terms & Conditions carefully before accessing or using our website. By accessing or using any part of the site, you agree to be bound by them. If you do not agree to all the terms and conditions of this agreement, then you may not access the website or use any services. We reserve the right to update, change or replace any part of these Terms & Conditions by posting updates and/or changes to our website. It is your responsibility to check this page periodically for changes. Your continued use of or access to the website following the posting of any changes constitutes acceptance of those changes. ",-1),p={class:"text-xl font-semibold text-gray-900 mt-4"},f={class:"mt-2 text-sm text-gray-500"},g=e("div",{class:"text-gray-500 mt-4 text-sm"},[r(" We reserve the right, at our sole discretion, to update, change or replace any part of these Terms & Conditions by posting updates and changes to our website. It is your responsibility to check our website periodically for changes. Your continued use of or access to our website or the service following the posting of any changes to these Terms & Conditions constitutes acceptance of those changes. Questions about the Terms & Conditions should be sent to us at "),e("a",{class:"text-blue-500",href:"mail:xtremeinc.86@gmail.com"},"xtremeinc.86@gmail.com"),r(". ")],-1),N={__name:"TermsOfService",setup(b){const n=[{title:"1 – WEBSITE TERMS",description:"By agreeing to these Terms & Conditions, you represent that you are at least the age of majority in your state or province of residence, or that you are the age of majority in your state or province of residence and you have given us your consent to allow any of your minor dependents to use this site. You may not use our products for any illegal or unauthorized purpose nor may you violate any laws in your jurisdiction (including but not limited to copyright laws). You must not transmit any viruses or any code of a destructive nature. A breach or violation of any of these terms will result in an immediate termination of your services."},{title:"2 – GENERAL CONDITIONS",description:"We reserve the right to refuse service to anyone for any reason at any time. You understand that your content (not including credit card information), may be transferred unencrypted and involve: (a) transmissions over various networks; and (b) changes to conform and adapt to technical requirements of connecting networks or devices. For reserving a vehicle or ordering parts or service, credit card information is always encrypted during transfer over networks. You agree not to reproduce, duplicate, copy, sell, resell or exploit any portion of the service, use of the service, or access to the service or any contact on the website through which the service is provided, without express written permission by us."},{title:"3 – ACCURACY, COMPLETENESS AND TIMELINESS OF INFORMATION",description:"We are not responsible if information made available on this site is not accurate or complete or current. The material on this site is provided for general information only and should not be relied upon or used as the sole basis for making decisions without consulting primary, more accurate, more complete or more timely sources of information. Any reliance on the material on this site is at your own risk. We reserve the right to modify the contents of this site at any time, but we have no obligation to update any information on our site. You agree that it is your responsibility to monitor changes to our site."},{title:"4 – MODIFICATION TO THE SERVICE AND PRICES",description:"Prices for our products are subject to change without notice. We reserve the right at any time to modify or discontinue the service (or any part or content thereof) without notice at any time. We shall not be liable to you or to any third-party for any modification, price change, suspension or discontinuance of service."},{title:"5 – PRODUCTS OR SERVICES",description:"We have made every effort to display as accurately as possible the colors, images, and trim levels of vehicles available. We cannot guarantee that your computer monitor’s display of any color will be accurate. We reserve the right, but are not obligated, to limit the sales of our products or services to any person, geographic region or jurisdiction. We reserve the right to limit the quantities of any products or services that we offer. All descriptions of products or product pricing are subject to change at any time without notice, at the sole discretion of us. We reserve the right to discontinue any product at any time. Any offer for any product or service made on this site is void where prohibited."},{title:"6 – ACCURACY OF BILLING AND ACCOUNT INFORMATION",description:"If ordering parts or reserving a vehicle, we reserve the right to refuse any order you place with us. We may, in our sole discretion, limit or cancel quantities purchased per person, per household or per order. These restrictions may include orders placed by or under the same customer account, the same credit card, and/or orders that use the same billing and/or shipping address. In the event that we make a change to or cancel an order, we may attempt to notify you by contacting the e-mail and/or billing address/phone number provided at the time the order was made. We reserve the right to limit or prohibit orders that, in our sole judgment, appear to be placed by dealers, resellers or distributors. You agree to provide current, complete and accurate purchase and account information for all purchases made at our dealership. You agree to promptly update your account and other information, including your email address and credit card numbers and expiration dates, so that we can complete your transactions and contact you as needed."},{title:"7 – OPTIONAL TOOLS",description:"We may provide you with access to third-party tools over which we neither monitor nor have any control nor input. Any use by you of optional tools offered through the site is entirely at your own risk and discretion, and you should ensure that you are familiar with and approve of the terms on which tools are provided by the relevant third-party provider(s). We may also, in the future, offer new services and/or features through the website (including the release of new tools and resources). Such new features and/or services shall also be subject to these Terms & Conditions."},{title:"8 – THIRD PARTY LINKS",description:"Certain content, products and services available via our service may include materials from third-parties. Third-party links on this site may direct you to third-party websites that are not affiliated with us. We are not responsible for examining or evaluating the content or accuracy, and we do not warrant and will not have any liability or responsibility for any third-party materials or websites, or for any other materials, products, or services of third-parties."},{title:"9 – USER COMMENTS, FEEDBACK AND OTHER SUBMISSIONS",description:"If, at our request, you send certain specific submissions or, without a request from us, you send creative ideas, suggestions, proposals, plans, or other materials, whether online, by email, by postal mail, or otherwise (collectively, ‘comments’), you agree that we may, at any time, without restriction, edit, copy, publish, distribute, translate, and otherwise use in any medium any comments that you forward to us. We are and shall be under no obligation: (1) to maintain any comments in confidence; (2) to pay compensation for any comments; or (3) to respond to any comments. We may, but have no obligation to, monitor, edit, or remove content that we determine in our sole discretion is unlawful, offensive, threatening, libelous, defamatory, pornographic, obscene, or otherwise objectionable or violates any party’s intellectual property or these Terms & Conditions."},{title:"10 – PERSONAL INFORMATION",description:"Your submission of personal information through the website is governed by our Privacy Policy."},{title:"11 – ERRORS, INACCURACIES AND OMISSIONS",description:"Occasionally, there may be information on our site or in the service that contains typographical errors, inaccuracies, or omissions that may relate to product descriptions, pricing, promotions, offers, product shipping charges, transit times, and availability. We reserve the right to correct any errors, inaccuracies, or omissions, and to change or update information or cancel orders if any information on the website is inaccurate at any time without prior notice. We undertake no obligation to update, amend, or clarify information on any related website, including, without limitation, pricing information, except as required by law. No specified update or refresh date applied in the service or on any related website should be taken to indicate that all information in the Service or on any related website has been modified or updated."},{title:"12 – PROHIBITED USES",description:"In addition to other prohibitions as set forth in the Terms & Conditions, you are prohibited from using the site or its content for any unlawful purpose, to solicit others to perform or participate in any unlawful acts, to violate any international, federal, provincial, or state regulations, rules, laws, or local ordinances, to infringe upon or violate our intellectual property rights or the intellectual property rights of others, to harass, abuse, insult, harm, defame, slander, disparage, intimidate, or discriminate based on gender, sexual orientation, religion, ethnicity, race, age, national origin, or disability, to submit false or misleading information, to upload or transmit viruses or any other type of malicious code that will or may be used in any way that will affect the functionality or operation of the service or of any related website, other websites, or the Internet, to collect or track the personal information of others, to spam, phish, pretext, spider, crawl, or scrape, for any obscene or immoral purpose, or to interfere with or circumvent the security features of the service or any related website, other websites, or the Internet."},{title:"13 – DISCLAIMER OF WARRANTIES; LIMITATION OF LIABILITY",description:"We do not guarantee, represent, or warrant that your use of our service will be uninterrupted, timely, secure, or error-free. We do not warrant that the results that may be obtained from the use of the service will be accurate or reliable. You agree that from time to time we may remove the service for indefinite periods of time or cancel the service at any time, without notice to you. You expressly agree that your use of, or inability to use, the service is at your sole risk. The service and all products delivered to you are provided ‘as is’ and ‘as available’ for your use, without any representation, warranties, or conditions of any kind, either express or implied, including all implied warranties or conditions of merchantability, merchantable quality, fitness for a particular purpose, durability, title, and non-infringement. In no case, shall Xtreme Motors Inc., our directors, officers, employees, affiliates, agents, contractors, interns, suppliers, service providers, or licensees be liable for any injury, loss, claim, or any direct, indirect, incidental, punitive, special, or consequential damages of any kind, including, without limitation, lost profits, lost revenue, lost savings, loss of data, replacement costs, or any similar damages, whether based in contract, tort (including negligence), strict liability or otherwise, arising from your use of any of the service or any products procured using the service, or for any other claim related in any way to your use of the service or any product, including, but not limited to, any errors or omissions in any content, or any loss or damage of any kind incurred as a result of the use of the service or any content (or product) posted, transmitted, or otherwise made available via the service, even if advised of their possibility."},{title:"14 – INDEMNIFICATION",description:"You agree to indemnify, defend, and hold harmless Xtreme Motors Inc. and our parent, subsidiaries, affiliates, partners, officers, directors, agents, contractors, service providers, subcontractors, suppliers, interns, and employees, harmless from any claim or demand, including reasonable attorneys’ fees, made by any third-party due to or arising out of your breach of these Terms & Conditions or the documents they incorporate by reference, or your violation of any law or the rights of a third-party."},{title:"15 – SEVERABILITY",description:"In the event that any provision of these Terms & Conditions is determined to be unlawful, void, or unenforceable, such provision shall nonetheless be enforceable to the fullest extent permitted by applicable law, and the unenforceable portion shall be deemed to be severed from these Terms & Conditions, such determination shall not affect the validity and enforceability of any other remaining provisions."},{title:"16 – TERMINATION",description:"The obligations and liabilities of the parties incurred prior to the termination date shall survive the termination of this agreement for all purposes. These Terms & Conditions are effective unless and until terminated by either you or us. You may terminate them at any time by notifying us that you no longer wish to use our services, or when you cease using our site. If in our sole judgment you fail, or we suspect that you have failed, to comply with any term or provision, we also may terminate this agreement at any time without notice and you will remain liable for all amounts due up to and including the date of termination; and/or accordingly may deny you access to our services (or any part thereof)."},{title:"17 – ENTIRE AGREEMENT",description:"The failure of us to exercise or enforce any right or provision of these Terms & Conditions shall not constitute a waiver of such right or provision. These Terms & Conditions and any policies or operating rules posted by us on this site or in respect to service constitutes the entire agreement and understanding between you and us and govern your use of the service, superseding any prior or contemporaneous agreements, communications, and proposals, whether oral or written, between you and us."},{title:"18 – CHANGES TO TERMS OF SERVICE",description:"You can review the most current version of the Terms & Conditions at any time at this page."}];return(v,w)=>(o(),s(a,{title:"Privacy Policy"},{default:c(()=>[e("div",h,[m,y,(o(),l(u,null,d(n,t=>e("div",{key:t.title},[e("h2",p,i(t.title),1),e("p",f,i(t.description),1)])),64)),g])]),_:1}))}};export{N as default};
